def solve(inputs, readings):
    deposits = inputs["deposits"]
    counts = {"S": 0, "M": 0, "L": 0}
    uncollected = 0
    longest = 0

    def minutes(time_text):
        hour, minute = map(int, time_text.split(":"))
        return hour * 60 + minute

    for deposit in deposits:
        counts[deposit["size"]] += 1
        if deposit["out"] is None:
            uncollected += 1
        else:
            wait = minutes(deposit["out"]) - minutes(deposit["in"])
            longest = max(longest, wait)

    issue = readings["issue"]
    action = {
        "damaged": "claim",
        "missing": "investigate",
        "wrong_item": "investigate",
        "delayed": "apologise",
    }[issue]
    busiest = max(("S", "M", "L"), key=lambda size: counts[size])
    return f"{action} ({issue}) | {uncollected} uncollected | longest wait {longest} min | busiest size {busiest}"

def solve(inputs, readings):
    counts = {'A': 0, 'B': 0, 'C': 0, 'F': 0}
    top_name = None
    top_average = -1
    for line in inputs['marks'].splitlines():
        name, marks_text = line.split(':', 1)
        marks = [int(value.strip()) for value in marks_text.split(',')]
        average = (2 * sum(marks) + 3) // 6
        if average >= 70:
            grade = 'A'
        elif average >= 60:
            grade = 'B'
        elif average >= 50:
            grade = 'C'
        else:
            grade = 'F'
        counts[grade] += 1
        if average > top_average:
            top_average = average
            top_name = name.strip()
    effort = readings['effort']
    result = 'A {}, B {}, C {}, F {} | top {} | effort {}'.format(
        counts['A'], counts['B'], counts['C'], counts['F'], top_name, effort
    )
    if effort == 'low' and counts['F'] > 0:
        result += ' | meeting'
    return result

def solve(inputs, readings):
    event = readings['event']
    minimum = {'fundraiser': 4, 'cleanup': 6, 'food_bank': 3, 'tutoring': 2}
    rota = inputs['rota']
    volunteers = set()
    days_worked = {}
    short_days = []

    for day, names in rota.items():
        distinct_names = set(names)
        volunteers.update(distinct_names)
        for name in distinct_names:
            days_worked[name] = days_worked.get(name, 0) + 1
        if len(distinct_names) < minimum[event]:
            short_days.append(day)

    if days_worked:
        busiest_count = max(days_worked.values())
        busiest = min(name for name, count in days_worked.items() if count == busiest_count)
    else:
        busiest = 'none'

    short_text = ', '.join(short_days) if short_days else 'none'
    return f"{event}: {len(volunteers)} volunteers, short on {short_text}, busiest {busiest}"
